// APIChatChannelTopicTeamThread: build the channel topic api:chat:team:{team_id}:thread:{thread_id}.
func APIChatChannelTopicTeamThread(teamID string, threadID string) string {
	return "api:chat:team:" + teamID + ":thread:" + threadID
}

// JoinAPIChatChannelTeamThread: join api:chat:team:{team_id}:thread:{thread_id} on socket and return the typed channel.
func JoinAPIChatChannelTeamThread(ctx context.Context, socket *Socket, teamID string, threadID string, afterCursor *string, beforeCursor *string, includeMetadata *bool, limit *int) (*APIChatChannel, error) {
	topic := APIChatChannelTopicTeamThread(teamID, threadID)
	channel := socket.Channel(topic)
	payload := map[string]JSONValue{}
	if afterCursor != nil {
		payload["after_cursor"] = JSONOf(*afterCursor)
	}
	if beforeCursor != nil {
		payload["before_cursor"] = JSONOf(*beforeCursor)
	}
	if includeMetadata != nil {
		payload["include_metadata"] = JSONOf(*includeMetadata)
	}
	if limit != nil {
		payload["limit"] = JSONOf(*limit)
	}
	joinResponse, err := channel.Join(ctx, payload)
	if err != nil {
		return nil, err
	}
	return &APIChatChannel{Channel: channel, JoinResponse: joinResponse}, nil
}

