// OnMessageAdded: Broadcast when a new message is added to a thread
// Payloads that fail to decode as the declared type are dropped.
// The returned function unsubscribes.
func (c *APIChatChannel) OnMessageAdded(callback func(APIChatMessageAddedPayload)) func() {
	return c.Channel.On("message_added", func(payload JSONValue) {
		var decoded APIChatMessageAddedPayload
		if err := payload.Decode(&decoded); err != nil {
			return
		}
		callback(decoded)
	})
}

