// The returned function unsubscribes.
func (c *APIChatChannel) OnSystemEvent(callback func(APIChatSystemEventPayload)) func() {
	return c.Channel.On("system_event", func(payload JSONValue) {
		var decoded APIChatSystemEventPayload
		if err := payload.Decode(&decoded); err != nil {
			return
		}
		callback(decoded)
	})
}

// OnTyping: Broadcast when a participant (human or agent) starts or stops typing. Ephemeral; never persisted.
// Payloads that fail to decode as the declared type are dropped.
// The returned function unsubscribes.
func (c *APIChatChannel) OnTyping(callback func(APIChatTypingPayload)) func() {
	return c.Channel.On("typing", func(payload JSONValue) {
		var decoded APIChatTypingPayload
		if err := payload.Decode(&decoded); err != nil {
			return
		}
		callback(decoded)
	})
}
